import { html } from 'lit-html';

export default {
  title: 'Components/Button Group',
  component: 'bfl-button-group',
  tags: ['autodocs'],
  argTypes: {
    buttonCount: {
      control: { type: 'number' },
      description: 'Number of buttons in the group (e.g., 1 or 2)',
      defaultValue: 2,
    },
  },
};

const Template = ({ buttonCount }) => html`
  <bfl-button-group buttonCount=${buttonCount}>
    <bfl-cta-button class="outlined">Button 1</bfl-cta-button>
    ${buttonCount > 1 ? html`<bfl-cta-button class="gradient">Button 2</bfl-cta-button>` : ''}
  </bfl-button-group>
`;

export const TwoButtons = Template.bind({});
TwoButtons.args = {
  buttonCount: 2,
};

export const OneButton = Template.bind({});
OneButton.args = {
  buttonCount: 1,
};
